#!/usr/bin/env python
"""
ANV EQ Quote Desk  -  RMS LOC/ACC builder, import, analysis and results in one workspace.

  Quote  ->  Geocode  ->  RMS run  ->  Results            (every account is saved to a library and can be re-opened)

SINGLE-FILE BUILD: the helper modules (rms_preflight, rms_results, rms_workbook, rms_pdf, anv_store, rms_results_ui)
are embedded below as compressed text and registered as normal Python modules at start-up, so ONLY this one file needs
uploading. Each module loads on its own, so a problem in one can never take down the rest of the app.

Keys can live in Streamlit Secrets / environment variables (LI_API_KEY, RISKDATA_API_KEY, GROUPING_API_KEY,
INFORCE_ANALYSIS_ID, RMS_HOST). There is no sidebar: connection settings sit in a panel at the top of the page. The
three keys are read from the environment variables LI_API_KEY, RISKDATA_API_KEY and GROUPING_API_KEY (Posit Connect:
Vars tab); no input box is shown for a key that is already saved, and a pasted value is tidied (quotes, spaces, a
"Bearer" prefix). Every save is verified and copied to the shared folder (and to mirrors on this server). Marginal
Impact compares against the in-force portfolio picked at the top of the page (the short app ID and the long analysis
ID work interchangeably). Results can be emailed as the signed-in user (Microsoft SSO) with an account summary and
attachments. The quote library is stored in STORE_DIR (default: a folder in the home directory); every account run is also saved to a
timestamped folder under /mnt/from-posit/content/anv-eq-rms-modeller/ (local fallback if that mount is unavailable).
"""
